from itertools import combinations
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_three(a, b, c):
    return gcd(a, gcd(b, c))

def check_good_set(U):
    a, b, c = U

    # Condition 1: gcd(a, b, c) = 1
    if gcd_three(a, b, c) != 1:
        return False

    # Condition 2: For every pair, there exists a third element that is a divisor of their product.

    # Pair (a, b): Does c divide ab?
    if (a * b) % c != 0:
        return False

    # Pair (a, c): Does b divide ac?
    if (a * c) % b != 0:
        return False

    # Pair (b, c): Does a divide bc?
    if (b * c) % a != 0:
        return False

    return True

good_sets_data = []
elements = range(1, 11)

# Search for good sets U of size 3, where U is a subset of {1, 2, ..., 10}
for U in combinations(elements, 3):
    if check_good_set(U):
        product = U[0] * U[1] * U[2]
        good_sets_data.append((sorted(U), product))

# Sort by product for easy listing and checking
good_sets_data.sort(key=lambda x: x[1])

print("Found Good Sets (U, Product):")
for U, P in good_sets_data:
