def check_good_set(U):
    # Condition 1: gcd of any three distinct elements is 1
    if len(U) < 3:
        return False

    from math import gcd

    for i in range(len(U)):
        for j in range(i + 1, len(U)):
            for k in range(j + 1, len(U)):
                g = gcd(U[i], U[j])
                g = gcd(g, U[k])
                if g != 1:
                    return False

    # Condition 2: For any two distinct elements, there exists another element that is a divisor of their product.
    U_set = set(U)
    for i in range(len(U)):
        for j in range(i + 1, len(U)):
            x = U[i]
            y = U[j]
            xy = x * y

            found_divisor = False
            for z in U_set:
                # The problem says "there exists another element". If |U|=3, and we check (x, y), the other element is z.
                # If |U|>3, z must be distinct from x and y if we interpret "another element" strictly.
                # Let's assume z can be any element in U, but usually it means z != x and z != y.
                if z != x and z != y and xy % z == 0:
                    found_divisor = True
                    break

            if not found_divisor:
                return False

    return True

