import itertools
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_list(numbers):
    if not numbers:
        return 0
    result = numbers[0]
    for i in range(1, len(numbers)):
        result = gcd(result, numbers[i])
    return result

def check_good_set(U):
    """
    Checks if a set U satisfies the two conditions for a good set.
    U must contain distinct positive integers.
    """
    n = len(U)
    if n < 3:
        return False

    # Condition 1: GCD of any three distinct elements is 1.
    for indices in itertools.combinations(range(n), 3):
        a, b, c = U[indices[0]], U[indices[1]], U[indices[2]]
        if gcd_list([a, b, c]) != 1:
            return False

    # Condition 2: For any two distinct elements (u_i, u_j), there exists another element (u_k) that is a divisor of their product (u_i * u_j).
    for i in range(n):
        for j in range(i + 1, n):
            u_i = U[i]
            u_j = U[j]
            product = u_i * u_j

            found_divisor = False
            # Check all other elements u_k
            for k in range(n):
                if k != i and k != j:
                    u_k = U[k]
                    if product % u_k == 0:
                        found_divisor = True
                        break

            if not found_divisor:
                return False

    return True

# Primes allowed
primes = [2, 3, 5, 7, 11]

# Generate candidate elements U_i <= 80 using only allowed primes
candidates = []
for i in range(1, 81):
    is_candidate = True
    temp_i = i
    for p in primes:
        if p*p > temp_i and temp_i > 1:
            break
        while temp_i % p == 0:
            temp_i //= p

    if temp_i == 1 and i > 1:
        candidates.append(i)

candidates.sort()

print(f"Number of candidate elements generated: {len(candidates)}")

# Search for good sets of size 4
found_sets = []
min_product = float('inf')

# Iterate over combinations of 4 distinct candidates
# Note: This remains computationally intensive, but necessary for systematic search.
for U_tuple in itertools.combinations(candidates, 4):
    U = list(U_tuple)

    current_product = math.prod(U)
    if current_product >= min_product:
        continue

    if check_good_set(U):
        product = math.prod(U)
        found_sets.append({'U': U, 'Product': product})
        min_product = product

# Sort the found sets by product
found_sets.sort(key=lambda x: x['Product'])

print("--- Found Good Sets of Size 4 ---")
if found_sets:
    for i, fs in enumerate(found_sets):
        print(f"Rank {i+1}: Product={fs['Product']}, Set={fs['U']}")
else:
    print("No good sets of size 4 found within the current search bound (u_i <= 80).")

print(f"Total good sets found: {len(found_sets)}")
